'use strict';
const form=document.querySelector('#tracking'),core=SubmissionCore,key='task-author-stage5-v1';let history=[],archiveHash='',archiveName='',hashing=false,hashVersion=0;
function read(k){try{return JSON.parse(localStorage.getItem(k)||'null');}catch{return null;}}
for(const [id,label]of core.gates){const row=document.createElement('label');row.className='gate';row.append(document.createTextNode(label));const select=document.createElement('select');select.name='gate_'+id;for(const [value,text]of [['pending','Pending'],['running','Running'],['passed','Passed · reported'],['task-failure','Task failure'],['infra-failure','Infrastructure failure']])select.add(new Option(text,value));row.append(select);document.querySelector('#gates').append(row);}
function values(){const d={gates:{},archiveHash,archiveName};for(const e of form.elements)if(e.name){if(e.name.startsWith('gate_'))d.gates[e.name.slice(5)]=e.value;else d[e.name]=e.type==='checkbox'?e.checked:e.value;}return d;}
function hydrate(raw){const d=core.normalize(raw);form.reset();for(const e of form.elements)if(e.name){if(e.name.startsWith('gate_'))e.value=d.gates[e.name.slice(5)];else if(e.type==='checkbox')e.checked=d[e.name]===true;else if(Object.hasOwn(d,e.name))e.value=d[e.name];}archiveHash=d.archiveHash;archiveName=d.archiveName;archiveLabel();metrics();}
function archiveLabel(){document.querySelector('#archiveStatus').textContent=archiveHash?`${archiveName||'Saved ZIP'} · SHA-256: ${archiveHash} (checksum recorded locally; reselect to recompute)`:'No ZIP checksum recorded.';}
function metrics(){const d=values(),invalid=d.decision==='approved'&&core.validate(d,history).length;const p=invalid?{amount:0,state:'approval draft incomplete; no payable amount recorded'}:core.payout(d);document.querySelector('#paymentAmount').textContent=`$${p.amount} USD`;document.querySelector('#paymentState').textContent=p.state+' · self-reported';}
function save(){try{localStorage.setItem(key,JSON.stringify({schema:'task-author.tracking.v1',draft:values(),history}));document.querySelector('#status').textContent='Draft saved locally. Append a record to update status history.';}catch{document.querySelector('#status').textContent='Storage unavailable. Export a tracker backup.';}metrics();}
function feedback(title,items){const out=document.querySelector('#feedback');out.replaceChildren();const h=document.createElement('h2');h.textContent=title;out.append(h);const ul=document.createElement('ul');for(const item of items){const li=document.createElement('li');li.textContent=item;ul.append(li);}out.append(ul);out.hidden=false;out.scrollIntoView({behavior:'smooth'});}
function renderHistory(){const el=document.querySelector('#history');el.replaceChildren();if(!history.length){const p=document.createElement('p');p.textContent='No status records yet. No submission, approval, or payment has been verified.';el.append(p);}for(const record of [...history].reverse()){const row=document.createElement('div');row.className='record';const h=document.createElement('h3');h.textContent=`${record.slug} · revision ${record.revision} · ${record.decision} (self-reported)`;row.append(h);const p=document.createElement('p');p.textContent=`${record.recordedAt} · Submission: ${record.submission} · Payment: ${core.payout(record).state}`;row.append(p);const details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent='Recorded fields and references';pre.textContent=JSON.stringify(record,null,2);details.append(summary,pre);row.append(details);el.append(row);}}
form.addEventListener('input',()=>{save();document.querySelector('#feedback').hidden=true;});form.addEventListener('change',e=>{if(e.target.id!=='archive'&&e.target.id!=='importFile'){save();document.querySelector('#feedback').hidden=true;}});
document.querySelector('#archive').onchange=async e=>{const f=e.target.files[0];if(!f)return;const version=++hashVersion;hashing=true;archiveHash='';archiveName='';document.querySelector('#archiveStatus').textContent='Computing local ZIP checksum…';try{if(!f.name.toLowerCase().endsWith('.zip'))throw Error('Select a ZIP file');if(f.size>100*1024*1024)throw Error('ZIP exceeds this app’s 100 MB limit');const bytes=await f.arrayBuffer();const head=new Uint8Array(bytes,0,Math.min(4,bytes.byteLength));if(head[0]!==80||head[1]!==75)throw Error('File does not have a ZIP signature');const hash=await crypto.subtle.digest('SHA-256',bytes);if(version!==hashVersion)return;archiveHash=[...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('');archiveName=f.name;archiveLabel();save();}catch(err){if(version!==hashVersion)return;archiveHash='';archiveName='';document.querySelector('#archiveStatus').textContent=err.message;save();}finally{if(version===hashVersion)hashing=false;}};
form.onsubmit=e=>{e.preventDefault();if(hashing)return feedback('Wait for ZIP checksum',['The selected ZIP is still being hashed.']);const d=values(),errors=core.validate(d,history);if(errors.length)return feedback('Status record needs attention',errors);const record={...d,id:crypto.randomUUID(),recordedAt:new Date().toISOString(),provenance:'self-reported; external platform not connected'};history.push(record);save();renderHistory();feedback('Status record appended',['No external submission or verification occurred. The difficulty threshold contradiction remains unresolved.']);};
document.querySelector('#export').onclick=()=>{save();const p={schema:'task-author.tracking.v1',exportedAt:new Date().toISOString(),draft:values(),history,ruleStatus:{difficultyBand:'unresolved',externalVerification:false}},u=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='submission-tracker.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
document.querySelector('#import').onclick=()=>document.querySelector('#importFile').click();document.querySelector('#importFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Backup exceeds 5 MB');const p=JSON.parse(await f.text());if(p.schema!=='task-author.tracking.v1'||!Array.isArray(p.history)||p.history.length>1000)throw Error('Unrecognized tracker backup');const imported=p.history.map(r=>({...core.normalize(r),id:typeof r.id==='string'?r.id:crypto.randomUUID(),recordedAt:typeof r.recordedAt==='string'?r.recordedAt:new Date().toISOString(),provenance:'imported self-report; not externally verified'}));for(const r of imported){const problems=core.validate(r,[]);if(problems.length)throw Error('Imported record violates tracking rules: '+problems.join(' '));}const d=core.normalize(p.draft);const ids=new Set(history.map(r=>r.id));for(const r of imported)if(!ids.has(r.id)){history.push(r);ids.add(r.id);}hydrate(d);save();renderHistory();feedback('Backup imported',['History merged by record ID; existing records preserved. Imported decisions remain unverified self-reports.']);}catch(err){feedback('Import failed',[err.message]);}e.target.value='';};
const old=read(key);if(old?.schema==='task-author.tracking.v1'){try{history=Array.isArray(old.history)?old.history.filter(r=>r&&typeof r==='object').map(r=>({...core.normalize(r),id:r.id,recordedAt:r.recordedAt,provenance:r.provenance})):[];hydrate(old.draft);}catch{history=[];}}else{const spec=read('task-author-stage2-v1')?.data;if(spec?.slug)form.elements.slug.value=spec.slug;}
const validation=read('task-author-stage4-v1');document.querySelector('#validationContext').textContent=validation?'Stage 4 review notes are available locally. They do not establish platform approval. Open Validation to inspect actual runner evidence.':'No stage 4 review notes found in this browser. Local execution and review remain pending.';archiveLabel();metrics();renderHistory();
